import random
import string
from typing import List, Tuple

# This generator produces valid Augeas path expressions and related strings
# suited for the provided fuzzer stubs. It focuses on syntactically valid
# and meaningful paths that exercise diverse behaviors: absolute and variable
# paths, indices, wildcards, predicates, and common file-oriented subtrees.
# It returns bytes; the fuzzer will split/consume them to feed FUZZ_PARAM_STR
# and related calls.

MAX_BYTES = 4096

# --- Helpers to build valid Augeas paths ---

LABEL_CHARS = string.ascii_letters + string.digits + "-_:."

COMMON_FILE_PATHS = [
    "/etc/hosts",
    "/etc/passwd",
    "/etc/group",
    "/etc/fstab",
    "/etc/ssh/sshd_config",
    "/etc/ssh/ssh_config",
    "/etc/sysctl.conf",
    "/etc/resolv.conf",
]

# Typical labels seen in Augeas trees
COMMON_LABELS = [
    "files",          # top tree for files
    "augeas",         # metadata subtree
    "root",
    "dir",
    "file",
    "line",
    "record",
    "entry",
    "comment",
    "value",
    "key",
    "type",
    "option",
    "param",
    "alias",
]

# Useful predicates keys frequently available
PRED_KEYS = ["label", "value", "file", "incl", "excl", "lens"]


def rnd(r: random.Random, seq):
    return r.choice(seq)


def make_label(r: random.Random) -> str:
    if r.random() < 0.7:
        return rnd(r, COMMON_LABELS)
    # random safe label
    n = r.randint(1, 10)
    return ''.join(r.choice(LABEL_CHARS) for _ in range(n))


def make_index(r: random.Random) -> str:
    # Augeas uses 1-based indices in paths; 0 is special (no siblings) for some APIs
    if r.random() < 0.2:
        return "[last()]"
    return f"[{r.randint(1, 5)}]"


def make_predicate(r: random.Random) -> str:
    # Basic predicates like [label()="foo"], [value()=~"regex"], [@label="foo"]
    kind = r.random()
    if kind < 0.34:
        return f"[label()='{make_label(r)}']"
    elif kind < 0.68:
        # Use equality on value(); avoid regex here for simplicity, keep valid
        v = random_value_literal(r)
        return f"[value()='{v}']"
    else:
        # attribute-style predicate commonly used in Augeas lenses trees
        key = rnd(r, PRED_KEYS)
        v = random_value_literal(r)
        return f"[@{key}='{v}']"


def random_value_literal(r: random.Random) -> str:
    # Favor printable, avoid quotes inside
    pool = string.ascii_letters + string.digits + "-_.:/@"
    n = r.randint(0, 8)
    return ''.join(r.choice(pool) for _ in range(n))


def make_segment(r: random.Random) -> str:
    t = r.random()
    if t < 0.20:
        return "*"  # wildcard
    seg = make_label(r)
    # optionally decorate with index or predicate
    if t < 0.55:
        seg += make_index(r)
    elif t < 0.90:
        # 0,1, or 2 predicates
        k = r.randint(0, 2)
        for _ in range(k):
            seg += make_predicate(r)
    return seg


def make_absolute_files_path(r: random.Random) -> str:
    # Paths under /files mapping to real filesystem paths
    fs = rnd(r, COMMON_FILE_PATHS)
    # Build Augeas /files/... tree representation
    parts = ["files"] + [p for p in fs.split('/') if p]
    # Optionally add entry/line/value nodes typical in many lenses
    if r.random() < 0.5:
        parts.append(rnd(r, ["entry", "line", "record"]))
        if r.random() < 0.5:
            parts.append(rnd(r, ["value", "key", "option"]))
    # Add indices or predicates occasionally
    built = []
    for p in parts:
        seg = p
        if r.random() < 0.5:
            seg += make_index(r)
        elif r.random() < 0.3:
            seg += make_predicate(r)
        built.append(seg)
    return "/" + "/".join(built)


def make_augeas_meta_path(r: random.Random) -> str:
    # e.g. /augeas/load/<X>/lens, incl, excl
    parts = ["augeas", "load", make_label(r)]
    # lens node is singular and common; include/incl/excl are common
    tail = rnd(r, ["lens", "incl", "excl", "module", "error"])
    parts.append(tail)
    if r.random() < 0.5:
        parts.append(rnd(r, ["source", "message", "line"]))
    # Add indices optionally
    path_parts = []
    for p in parts:
        if r.random() < 0.5:
            p = p + make_index(r)
        path_parts.append(p)
    return "/" + "/".join(path_parts)


def make_variable_name(r: random.Random) -> str:
    # Variables are referenced as $name; keep them simple
    first = r.choice(string.ascii_letters + "_")
    rest = ''.join(r.choice(string.ascii_letters + string.digits + "_") for _ in range(r.randint(0, 6)))
    return first + rest


def make_variable_path(r: random.Random) -> str:
    # Use a variable reference in a path context, e.g., $X[1]/value
    var = make_variable_name(r)
    # Following segment(s)
    segs = []
    if r.random() < 0.7:
        segs.append(make_segment(r))
        if r.random() < 0.5:
            segs.append(make_segment(r))
    suffix = ("/" + "/".join(segs)) if segs else ""
    return f"${var}{suffix}"


def make_generic_absolute_path(r: random.Random) -> str:
    # Generic absolute path with mixed segments
    nseg = r.randint(1, 6)
    parts = [make_segment(r) for _ in range(nseg)]
    return "/" + "/".join(parts)


def make_path(r: random.Random) -> str:
    choice = r.random()
    if choice < 0.40:
        return make_absolute_files_path(r)
    elif choice < 0.65:
        return make_generic_absolute_path(r)
    elif choice < 0.80:
        return make_augeas_meta_path(r)
    else:
        return make_variable_path(r)


# --- Other strings for non-path parameters ---

LENS_NAMES = [
    # Common shipped lenses; names are examples and may be present in most installs
    "Hosts.lns", "Passwd.lns", "Group.lns", "Fstab.lns", "Sshd.lns", "Sysctl.lns", "Resolv.lns",
    # Module form without .lns where autoload uses lns
    "Hosts", "Passwd", "Group", "Fstab", "Sshd", "Sysctl", "Resolv",
]


def make_lens_name(r: random.Random) -> str:
    return rnd(r, LENS_NAMES)


def make_label_value(r: random.Random) -> str:
    # Valid label for aug_insert/rename; must not contain '/', '*', or bracketed index
    return make_label(r)


def make_free_text(r: random.Random) -> str:
    # For values and text commands; keep printable and short
    n = r.randint(0, 40)
    pool = string.ascii_letters + string.digits + " -_./:@,#$%+="
    return ''.join(r.choice(pool) for _ in range(n))


# --- Serialization: build a blob that the fuzzer will slice for FUZZ_PARAM_STR ---
# We will emit a sequence of length-prefixed strings. Many fuzzers read sequentially.
# Even if the harness uses a different splitter, providing a rich set of valid strings
# up front increases the likelihood of valid combinations.


def pack_lp_strings(strs: List[str]) -> bytes:
    out = bytearray()
    for s in strs:
        b = s.encode('utf-8')
        # 2-byte length prefix (little endian), cap each at 512 to keep under 4096 total
        if len(b) > 512:
            b = b[:512]
        out += len(b).to_bytes(2, 'little')
        out += b
    return bytes(out)


def make_string_corpus(r: random.Random) -> List[str]:
    strs: List[str] = []

    # Paths heavily used by many stubs
    for _ in range(12):
        strs.append(make_path(r))

    # Some exact, common useful paths
    strs += [
        "/files/etc/passwd",
        "/files/etc/passwd/*",
        "/files/etc/hosts",
        "/files/etc/ssh/sshd_config",
        "/augeas/load/*",
        "/augeas/load/*/lens",
        "/augeas/load/*/incl",
        "/augeas/load/*/excl",
    ]

    # Variable names and references for defvar/defnode use
    for _ in range(4):
        var = make_variable_name(r)
        strs.append(var)            # NAME parameter
        strs.append(f"${var}")     # variable reference

    # Lens names for text_store/retrieve/transform
    for _ in range(6):
        strs.append(make_lens_name(r))

    # Labels for insert/rename
    for _ in range(6):
        strs.append(make_label_value(r))

    # Some simple values
    for _ in range(12):
        strs.append(make_free_text(r))

    # Include a few file system paths for aug_transform/aug_load_file
    for _ in range(6):
        strs.append(rnd(r, COMMON_FILE_PATHS))

    # Commands for aug_srun (even if not directly used, harmless strings)
    cmds = [
        "print /files",
        "match /files/etc/hosts/*",
        "get /files/etc/passwd/1",
        "set /augeas/load/Hosts/lens 'Hosts.lns'",
        "set /augeas/load/Hosts/incl '/etc/hosts'",
        "save",
    ]
    strs.extend(cmds)

    # Ensure uniqueness while preserving order to improve diversity
    seen = set()
    uniq = []
    for s in strs:
        if s not in seen:
            seen.add(s)
            uniq.append(s)

    return uniq


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    strs = make_string_corpus(r)
    blob = pack_lp_strings(strs)
    if len(blob) > MAX_BYTES:
        blob = blob[:MAX_BYTES]
    return blob
